import { authenticateUser } from "@/server/auth/principal";
import { contentDisposition, route } from "@/server/http";
import { labelStock, renderZpl } from "@/server/labels/zpl";
import { getLabelProfiles } from "@/server/services/label-templates";
import { contentFor } from "@/server/services/printing";

const ids = (v: string | null) => (v ?? "").split(",").filter((x) => /^[0-9a-f-]{36}$/i.test(x)).slice(0, 1000);

/** ZPL II file for thermal label printers: `?items=<id,…>&locations=<id,…>&size=57x32` — generated by the one label engine. */
export const GET = route(async (req) => {
  const user = await authenticateUser(req, "label.print");
  const p = new URL(req.url).searchParams;
  const labels = [];
  for (const id of ids(p.get("items"))) {
    const c = await contentFor(user.organizationId, "BOOK", id);
    if (c) labels.push(c);
  }
  for (const id of ids(p.get("locations"))) {
    const c = await contentFor(user.organizationId, "LOCATION", id);
    if (c) labels.push(c);
  }
  const body = await renderZpl(labels, { stock: labelStock(p.get("size")), profiles: await getLabelProfiles(user.organizationId) });
  return new Response(body, {
    headers: { "content-type": "text/plain; charset=utf-8", "content-disposition": contentDisposition(`labels-${labels.length}.zpl`, true), "cache-control": "no-store" },
  });
});
